namespace Battleship.Shared;

public static class BoardCoords
{
    public const int Size = 10;

    public static bool TryParse(string? text, out int row, out int col)
    {
        row = -1;
        col = -1;
        if (string.IsNullOrWhiteSpace(text))
        {
            return false;
        }

        var trimmed = text.Trim().ToUpperInvariant();
        if (trimmed.Length is < 2 or > 3)
        {
            return false;
        }

        var letter = trimmed[0];
        if (letter is < 'A' or > 'J')
        {
            return false;
        }

        if (!int.TryParse(trimmed.AsSpan(1), out var number) || number is < 1 or > 10)
        {
            return false;
        }

        row = letter - 'A';
        col = number - 1;
        return true;
    }

    public static bool InBounds(int row, int col) =>
        row is >= 0 and < Size && col is >= 0 and < Size;

    public static string Format(int row, int col) => ProtocolInfo.FormatCoordinate(row, col);
}

namespace Battleship.Shared;

public sealed class ProtocolMessage
{
    public int? V { get; set; }
    public MessageType? Type { get; set; }
    public int? Seq { get; set; }
    public string? Coord { get; set; }
    public ShotOutcome? Outcome { get; set; }
    public ShipKind? Ship { get; set; }
    public string? Text { get; set; }
    public ProtocolErrorCode? Code { get; set; }
    public string? Detail { get; set; }

    public static ProtocolMessage Hello() => new()
    {
        V = ProtocolInfo.Version,
        Type = MessageType.HELLO
    };

    public static ProtocolMessage Ready() => new()
    {
        V = ProtocolInfo.Version,
        Type = MessageType.READY
    };

    public static ProtocolMessage Shot(int seq, string coordinate) => new()
    {
        V = ProtocolInfo.Version,
        Type = MessageType.SHOT,
        Seq = seq,
        Coord = coordinate
    };

    public static ProtocolMessage Result(int seq, ShotOutcome outcome, ShipKind? ship = null) => new()
    {
        V = ProtocolInfo.Version,
        Type = MessageType.RESULT,
        Seq = seq,
        Outcome = outcome,
        Ship = ship
    };

    public static ProtocolMessage Chat(string text) => new()
    {
        V = ProtocolInfo.Version,
        Type = MessageType.CHAT,
        Text = text
    };

    public static ProtocolMessage Quit() => new()
    {
        V = ProtocolInfo.Version,
